CREATE OR REPLACE FUNCTION public.kompass_english_start_skill_check(p_token text,p_pin text,p_task_key text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE gate jsonb;l kompass_english_links;t kompass_english_tasks;items jsonb;id uuid;
BEGIN
 gate:=kompass_english_access_window(p_token,p_pin);
 IF coalesce((gate->>'open')::boolean,false) IS NOT true THEN RETURN gate||jsonb_build_object('ok',false);END IF;
 SELECT * INTO STRICT l FROM kompass_english_links WHERE active AND token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') FOR UPDATE;
 SELECT * INTO t FROM kompass_english_tasks WHERE task_key=p_task_key AND is_assessment AND (assessment_config->>'server_check')::boolean;
 IF NOT FOUND THEN RAISE EXCEPTION 'Kompetenztest nicht freigegeben.';END IF;
 IF (SELECT count(*) FROM kompass_english_vocab_attempts WHERE grade=l.grade AND pupil_id=l.pupil_id AND created_at>clock_timestamp()-interval '1 day')>=100 THEN RAISE EXCEPTION 'Zu viele Teststarts.';END IF;
 items:=t.vocabulary_bank->'check_items';
 IF jsonb_array_length(items)<>13 THEN RAISE EXCEPTION 'Aufgabenpool unvollständig.';END IF;
 INSERT INTO kompass_english_vocab_attempts(grade,pupil_id,task_key,level,items,max_points,test_date) VALUES(l.grade,l.pupil_id,p_task_key,'COMMON',items,26,(gate->>'test_date')::date) RETURNING kompass_english_vocab_attempts.id INTO id;
 RETURN jsonb_build_object('ok',true,'id',id,'items',(SELECT jsonb_agg(q-'accepted') FROM jsonb_array_elements(items) q),'max_points',26,'test_date',gate->>'test_date');
END $$;
REVOKE ALL ON FUNCTION public.kompass_english_start_skill_check(text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.kompass_english_start_skill_check(text,text,text) TO anon,authenticated;
COMMIT;